std::vector<int> findSubstring(const std::string& s, const std::vector<std::string>& words) {
    if (s.empty() || words.empty()) {
        return {};
    }

    int wordLength = words[0].size();
    int totalWords = words.size();
    int totalLength = wordLength * totalWords;

    std::unordered_map<std::string, int> wordCount;
    for (const auto& word : words) {
        wordCount[word]++;
    }

    std::vector<int> result;

    for (int i = 0; i <= s.size() - totalLength; i++) {
        std::unordered_map<std::string, int> tempWordCount;
        for (int j = 0; j < totalWords; j++) {
            std::string currentWord = s.substr(i + j * wordLength, wordLength);
            if (wordCount.find(currentWord) == wordCount.end()) {
                break;
            }
            tempWordCount[currentWord]++;
            if (tempWordCount[currentWord] > wordCount[currentWord]) {
                break;
            }
            if (j + 1 == totalWords) {
                result.push_back(i);
            }
        }
    }

    return result;
}
