public class Solution {
    public int[] nextPermutation(int[] nums) {
        int n = nums.length;
        int k = -1;
        for (int i = n - 1; i > 0; i--) {
            if (nums[i - 1] < nums[i]) {
                k = i - 1;
                break;
            }
        }
        if (k == -1) {
            Arrays.reverse(nums);
        } else {
            int l = 0;
            for (int i = n - 1; i > k; i--) {
                if (nums[i] > nums[k]) {
                    l = i;
                    break;
                }
            }
            int temp = nums[k];
            nums[k] = nums[l];
            nums[l] = temp;
            nums[k + 1:] = Arrays.copyOfRange(nums, k + 1, n);
        }
        return nums;
    }
}
