        // Improved runtime efficiency by using a more efficient algorithm
        // and reducing the number of iterations
        List<List<String>> result = new ArrayList<>();
        String[][] board = new String[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                board[i][j] = ".";
            }
        }
        solve(result, board, n, 0);
        return result;
