        for (int i = 0; i < board.length; i++) {
            if (board[i][col] == 1) {
                return false;
            }
        }
        for (int i = 0; i < board.length; i++) {
            if (Math.abs(i - row) == Math.abs(i - col)) {
                return false;
            }
        }
        return true;
    }
