public int minPathSum(int[][] grid) {
    int m = grid.length;
    int n = grid[0].length;

    // Initialize the first row and column with their minimum values
    for (int i = 1; i < m; i++) {
        grid[i][0] += grid[i - 1][0];
    }
    for (int i = 1; i < n; i++) {
        grid[0][i] += grid[0][i - 1];
    }

    // Fill the rest of the grid with the minimum values from the adjacent cells
    for (int i = 1; i < m; i++) {
        for (int j = 1; j < n; j++) {
            grid[i][j] += Math.min(grid[i - 1][j], grid[i][j - 1]);
        }
    }

    // Return the minimum value in the bottom-right cell
    return grid[m - 1][n - 1];
}
