int maximalRectangle(char** matrix, int matrixSize, int* matrixColSize) {
    // Base case: if the matrix is empty, return 0
    if (matrixSize == 0) {
        return 0;
    }

    // Initialize a stack to store the indices of the matrix
    int* stack = (int*) malloc(matrixSize * sizeof(int));
    int top = -1;

    // Iterate over the rows of the matrix
    for (int i = 0; i < matrixSize; i++) {
        // Initialize a variable to store the current height
        int height = 0;

        // Iterate over the columns of the current row
        for (int j = 0; j < matrixColSize[i]; j++) {
            // If the current cell is 1, update the height
            if (matrix[i][j] == '1') {
                height++;
            } else {
                // If the current cell is 0, pop the stack until the height is 0
                while (height > 0) {
                    int area = (matrixSize - top - 1) * stack[top];
                    top--;
                    height--;
                }
            }
        }

        // Push the current height onto the stack
        stack[++top] = height;
    }

    // Calculate the area of the largest rectangle
    int maxArea = 0;
    for (int i = 0; i <= top; i++) {
        int area = (matrixSize - top - 1) * stack[i];
        maxArea = max(maxArea, area);
    }

    // Free the allocated memory for the stack
    free(stack);

    return maxArea;
}

