// Function to find the largest rectangle in a 2D binary matrix
int maximalRectangle(std::vector<std::vector<char>>& matrix) {
    // Base case: if the matrix is empty, return 0
    if (matrix.empty()) {
        return 0;
    }

    // Initialize a stack to store the indices of the matrix
    std::stack<std::pair<int, int>> stack;
    int maxArea = 0;

    // Iterate over the rows of the matrix
    for (int i = 0; i < matrix.size(); i++) {
        // Initialize a variable to store the current height
        int height = 0;

        // Iterate over the columns of the current row
        for (int j = 0; j < matrix[i].size(); j++) {
            // If the current cell is 1, update the height
            if (matrix[i][j] == '1') {
                height++;
            } else {
                // If the current cell is 0, pop the stack until the height is 0
                while (!stack.empty() && matrix[i][stack.top().first] == '0') {
                    int width = j - stack.top().first - 1;
                    int area = height * width;
                    maxArea = std::max(maxArea, area);
                    height = 0;
                    stack.pop();
                }
                if (!stack.empty()) {
                    height--;
                }
            }
        }

        // Push the current height onto the stack
        stack.push({j, i});
    }

    // Calculate the area of the largest rectangle
    while (!stack.empty()) {
        int width = matrix.size() - stack.top().first - 1;
        int area = height * width;
        maxArea = std::max(maxArea, area);
        height = 0;
        stack.pop();
    }

    return maxArea;
}

