    std::cout << "Output:  " << std::endl;
    std::vector<int> output = {0, -3, 9, -10, nullptr, 5};
    for (int i = 0; i < output.size(); i++) {
        std::cout << output[i] << ", ";
    }
    std::cout << std::endl;

    return 0;
}
