#include <iostream>
#include <vector>

std::vector<int> get_row(int rowIndex) {
    std::vector<int> row(rowIndex + 1, 1);
    for (int i = 1; i <= rowIndex; ++i) {
        for (int j = i - 1; j > 0; --j) {
            row[j] += row[j - 1];
        }
    }
    return row;
}

int main() {
    int rowIndex = 3;
    std::vector<int> result = get_row(rowIndex);
    for (int i = 0; i < result.size(); ++i) {
        std::cout << result[i] << " ";
    }
    std::cout << std::endl;
    return 0;
}
