```javascript
function getRow(rowIndex) {
    let row = [1];
    for (let i = 1; i <= rowIndex; i++) {
        let newRow = [];
        for (let j = 0; j <= i; j++) {
            newRow[j] = row[j] + (j === 0 ? 0 : row[j - 1]);
        }
        row = newRow;
    }
    return row;
}

