```rust
fn get_row(rowIndex: i32) -> Vec<i32> {
    let mut row = vec![1];
    for i in 1..=rowIndex {
        let mut newRow = vec![];
        for j in 0..=i {
            newRow.push(row[j] + (j == 0) as i32);
        }
        row = newRow;
    }
    row
}

fn main() {
    let rowIndex = 3;
    let result = get_row(rowIndex);
    for i in result.iter() {
        println!("{} ", i);
    }
    println!();
}
