```scala
object Solution {
    def getRow(rowIndex: Int): Array[Int] = {
        val row = Array.fill(rowIndex + 1)(1)
        for (i <- 1 to rowIndex) {
            for (j <- i to 0 by -1) {
                row(j) = row(j) + row(j - 1)
            }
        }
        row
    }
}

object Main {
    def main(args: Array[String]) {
        val rowIndex = 3
        val result = new Solution().getRow(rowIndex)
        for (i <- result) {
            println(s"$i ")
        }
        println()
    }
}
```



```swift
func getRow(_ rowIndex: Int) -> [Int] {
    var row = [Int](repeating: 1, count: rowIndex + 1)
    for i in 1...rowIndex {
        for j in (0...i).reversed() {
            row[j] = row[j] + row[j + 1]
        }
    }
    return row
}

// Test case
print(getRow(3).joined(separator: " ")) // 1 3 3 1
```



