int ladderLength(std::string beginWord, std::string endWord, std::vector<std::string>& wordList) {
    std::set<std::string> wordSet(wordList.begin(), wordList.end());
    if (!wordSet.count(endWord)) {
        return 0;
    }

    std::queue<std::string> q;
    q.push(beginWord);
    int steps = 1;

    while (!q.empty()) {
        int size = q.size();
        std::set<std::string> currentLevel;

        for (int i = 0; i < size; ++i) {
            std::string currentWord = q.front();
            q.pop();
            if (currentWord == endWord) {
                return steps;
            }

            for (int j = 0; j < currentWord.size(); ++j) {
                char originalChar = currentWord[j];
                for (int k = 0; k < 26; ++k) {
                    currentWord[j] = 'a' + k;
                    std::string newWord = currentWord;
                    if (wordSet.count(newWord)) {
                        q.push(newWord);
                        currentLevel.insert(newWord);
                    }
                }
                currentWord[j] = originalChar;
            }
        }

        wordSet -= currentLevel;
        steps++;
    }

    return 0;
}
