```go
package main

import (
	"container/heap"
	"sort"
	"strings"
)

func ladderLength(beginWord string, endWord string, wordList []string) int {
	wordSet := make(map[string]bool)
	for _, word := range wordList {
		wordSet[word] = true
	}

	if !wordSet[endWord] {
		return 0
	}

	q := &priorityQueue{}
	heap.Push(q, &node{beginWord, 1})
	steps := 1

	for q.Len() > 0 {
		node := heap.Pop(q).(*node)
		if node.word == endWord {
			return node.steps
		}

		for i := 0; i < len(node.word); i++ {
			for j := 'a'; j <= 'z'; j++ {
				newWord := strings.Replace(node.word, string(node.word[i]), string(j), -1)
				if wordSet[newWord] {
					wordSet[newWord] = false
					heap.Push(q, &node{newWord, node.steps + 1})
				}
			}
		}
	}

	return 0
}

type node struct {
	word string
	steps int
}

type priorityQueue []*node

func (pq priorityQueue) Len() int { return len(pq) }
func (pq priorityQueue) Less(i, j int) bool {
	return pq[i].steps < pq[j].steps
}
func (pq priorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
}
func (pq *priorityQueue) Push(x interface{}) {
	*pq = append(*pq, x.(*node))
}
func (pq *priorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	x := old[n-1]
	*pq = old[0 : n-1]
	return x
}
