public int longestConsecutive(int[] nums) {
    Set<Integer> elements = new HashSet<>(nums);
    int longestSeq = 0;

    for (int num : nums) {
        if (!elements.contains(num - 1)) {
            int currentNum = num;
            int currentSeq = 1;

            while (elements.contains(currentNum + 1)) {
                currentNum += 1;
                currentSeq += 1;
            }

            longestSeq = Math.max(longestSeq, currentSeq);
        }
    }

    return longestSeq;
}
