#include <string>
#include <set>
#include <vector>

bool wordBreak(std::string s, const std::vector<std::string>& wordDict) {
    std::set<std::string> wordSet(wordDict.begin(), wordDict.end());
    std::vector<bool> dp(s.size() + 1, false);
    dp[0] = true;
    for (int i = 1; i <= s.size(); ++i) {
        for (int j = i - 1; j >= 0; --j) {
            if (dp[j] && s.substr(j, i - j) in wordSet) {
                dp[i] = true;
                break;
            }
        }
    }
    return dp[s.size()];
}
