public class Solution {
    public List<String> wordBreak(String s, List<String> wordDict) {
        // Create a set to store the words in the dictionary
        Set<String> wordSet = new HashSet<>(wordDict);

        // Create a dictionary to store the results of the helper function
        Map<String, List<String>> memo = new HashMap<>();

        // Define the helper function
        String helper(String s, Set<String> dict, Map<String, List<String>> memo) {
            if (s.isEmpty()) {
                return new ArrayList<>();
            }

            List<String> res = new ArrayList<>();
            if (dict.contains(s)) {
                res.add(s);
            }

            for (int i = 1; i < s.length(); i++) {
                String prefix = s.substring(0, i);
                if (!dict.contains(prefix)) {
                    continue;
                }
                String suffix = s.substring(i);
                List<String> temp = helper(suffix, dict, memo);
                for (String t : temp) {
                    res.add(prefix + " " + t);
                }
            }

            memo.put(s, res);
            return res;
        }

        // Call the helper function with the input string and dictionary
        return helper(s, wordSet, memo);
    }
}
