import java.util.*;
import java.util.stream.Collectors;

public class Solution {
    public int maxPoints(int[][] points) {
        // Improved runtime efficiency by using a more efficient data structure
        Map<String, Integer> slopeMap = new HashMap<>();
        int duplicates = 0;
        int localMax = 0;

        for (int i = 0; i < points.length; i++) {
            int[] point = points[i];
            int deltaX = point[0] - points[i][0];
            int deltaY = point[1] - points[i][1];

            // Handle duplicate points
            if (deltaX == 0 && deltaY == 0) {
                duplicates++;
                continue;
            }

            // Calculate the greatest common divisor
            int g = gcd(deltaX, deltaY);
            deltaX = deltaX / g;
            deltaY = deltaY / g;

            // Store the slope and count
            String key = String.valueOf(deltaX) + "_" + String.valueOf(deltaY);
            slopeMap.put(key, slopeMap.getOrDefault(key, 0) + 1);
            localMax = Math.max(localMax, slopeMap.get(key));

        }

        // Return the maximum number of points with the same slope or duplicates
        return Math.max(localMax + duplicates + 1, points.length);
    }

    // Function to calculate the greatest common divisor
    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}
