    if (!root || !root->left) {
        return root;
    }

    TreeNode* new_root = upside_down_binary_tree(root->left);
    root->left->right = root;
    root->left->left = root->right;
    root->left = nullptr;
    root->right = nullptr;
    return new_root;
}

