```java
public class Solution {
    public int majorityElement(int[] nums) {
        int count = 0;
        int candidate = 0;

        for (int num : nums) {
            if (count == 0) {
                candidate = num;
            }
            count += (num == candidate) - (num != candidate);
        }

        return candidate;
    }
}

public class Main {
    public static void main(String[] args) {
        int[] nums = {3, 2, 3};
        System.out.println(new Solution().majorityElement(nums));
    }
}
