```python
import math

def calculateMinimumHP(dungeon):
    m = len(dungeon)
    n = len(dungeon[0])
    dp = [[0] * n for _ in range(m)]

    # Initialize the bottom-right cell
    if m == 1 and n == 1:
        dp[m - 1][n - 1] = max(0, dungeon[m - 1][n - 1])
    else:
        dp[m - 1][n - 1] = max(0, dungeon[m - 1][n - 1])

    # Fill the rest of the table
    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if i == m - 1 and j == n - 1:
                dp[i][j] = max(0, dungeon[i][j])
            elif i == m - 1:
                dp[i][j] = max(0, dp[i][j + 1] + dungeon[i][j])
            elif j == n - 1:
                dp[i][j] = max(0, dp[i + 1][j] + dungeon[i][j])
            else:
                dp[i][j] = max(0, max(dp[i + 1][j], dp[i][j + 1]) + dungeon[i][j])

    return abs(dp[0][0]) + 1

# Test case
