package main

import (
	"container/heap"
	"sort"
)

func containsNearbyAlmostDuplicate(nums []int, k int, t int) bool {
	// Use a min-heap to store the elements in the sliding window
	heap := &MinHeap{}
	for _, num := range nums {
		heap.Push(num)
		if heap.Len() > k+1 {
			heap.Pop()
		}
		// Check if any element in the heap is within the given range
		for heap.Len() > 0 {
			element := heap.Pop()
			if element-1 <= t && element+1 >= t {
				return true
			}
			heap.Push(element)
		}
	}
	return false
}

type MinHeap struct {
	data []int
}

func (h *MinHeap) Push(x interface{}) {
	h.data = append(h.data, x.(int))
}

func (h *MinHeap) Pop() interface{} {
	old := h.data
	n := len(old)
	i := n - 1
	h.data = old[:i]
	x := old[i]
	return x
}

func (h *MinHeap) Len() int {
	return len(h.data)
}

func (h *MinHeap) Less(i, j int) bool {
	return h.data[i] < h.data[j]
}

