    const result = [];
    let start = nums[0];
    for (let i = 1; i < nums.length; i++) {
        if (nums[i] > nums[i-1] + 1) {
            if (start === nums[i-1]) {
                result.push(start.toString());
            } else {
                result.push(start + "->" + nums[i-1].toString());
            }
            start = nums[i];
        }
    }

    if (start === nums[nums.length-1]) {
        result.push(start.toString());
    } else {
        result.push(start + "->" + nums[nums.length-1].toString());
    }

    return result;
}

