#include <iostream>
#include <vector>
#include <string>

// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

std::vector<std::string> binaryTreePaths(TreeNode* root) {
    std::vector<std::string> paths;
    if (!root) {
        return paths;
    }
    if (!root->left && !root->right) {
        paths.push_back(std::to_string(root->val));
        return paths;
    }
    for (const auto& path : binaryTreePaths(root->left)) {
        paths.push_back(std::to_string(root->val) + "->" + path);
    }
    for (const auto& path : binaryTreePaths(root->right)) {
        paths.push_back(std::to_string(root->val) + "->" + path);
    }
    return paths;
}

int main() {
    TreeNode* root = new TreeNode(1);
    root->left = new TreeNode(2);
    root->right = new TreeNode(3);
    root->left->left = new TreeNode(5);
    std::vector<std::string> expected = {"1->2->5", "1->3"};
    std::vector<std::string> actual = binaryTreePaths(root);
    for (const auto& path : actual) {
        std::cout << path << std::endl;
    }
    return 0;
}
