    int count = 0;
    Arrays.sort(nums);
    for (int i = 0; i < nums.length; ++i) {
        int j = i + 1, k = nums.length - 1;
        while (j < k) {
            if (nums[i] + nums[j] + nums[k] < target) {
                count += k - j;
                j++;
            } else {
                k--;
            }
        }
    }
    return count;
}
