#include <iostream>
#include <vector>
#include <algorithm>

int nthSuperUglyNumber(int n, const std::vector<int>& primes) {
    std::vector<int> ugly(n, 0);
    ugly[0] = 1;
    std::vector<int> indices(primes.size(), 0);

    for (int i = 1; i < n; ++i) {
        int min_val = std::numeric_limits<int>::max();

        for (int j = 0; j < primes.size(); ++j) {
            min_val = std::min(min_val, ugly[indices[j]] * primes[j]);
        }

        ugly[i] = min_val;

        for (int j = 0; j < primes.size(); ++j) {
            if (ugly[i] == ugly[indices[j]] * primes[j]) {
                indices[j]++;
            }
        }
    }

    return ugly[n - 1];
}

int main() {
    int n = 12;
    std::vector<int> primes = {2, 7, 13, 19};
    std::cout << nthSuperUglyNumber(n, primes) << std::endl;
    return 0;
}
