public class Solution {
    public int[] countSmaller(int[] nums) {
        // Improved merge sort implementation
        int[] counts = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            counts[i] = 0;
        }

        // Merge sort the array
        mergeSort(nums, 0, nums.length - 1, counts);

        return counts;
    }

    private void mergeSort(int[] nums, int start, int end, int[] counts) {
        if (start == end) {
            return;
        }

        int mid = (start + end) / 2;
        mergeSort(nums, start, mid, counts);
        mergeSort(nums, mid + 1, end, counts);

        // Merge the two sorted subarrays
        merge(nums, start, mid, end, counts);
    }

    private void merge(int[] nums, int start, int mid, int end, int[] counts) {
        int[] left = new int[mid - start + 1];
        int[] right = new int[end - mid];

        for (int i = 0; i < left.length; i++) {
            left[i] = nums[start + i];
        }
        for (int i = 0; i < right.length; i++) {
            right[i] = nums[mid + 1 + i];
        }

        int i = 0, j = 0, k = start;
        while (i < left.length || j < right.length) {
            if (i < left.length && (j >= 0 || left[i] <= right[j])) {
                nums[k++] = left[i++];
            } else {
                counts[left[i - 1]] += j;
                nums[k++] = right[j++];
            }
        }
    }
}
