import java.util.*;

public class Solution {
    public int maxProduct(String[] words) {
        int n = words.length;
        int max_product = 0;

        // Create a mask for each word
        for (int i = 0; i < n; ++i) {
            int mask = 0;
            for (char c : words[i].toCharArray()) {
                mask |= 1 << (c - 'a');
            }
            // Find the intersection of masks
            for (int j = i + 1; j < n; ++j) {
                if ((mask & words[j].toCharArray()[0]) == 0) {
                    max_product = Math.max(max_product, words[i].length() * words[j].length());
                }
            }
        }

        return max_product;
    }
}
