import java.util.*;

public class CoinChange {
    public int coinChange(int[] coins, int amount) {
        // Initialize a 2D array to store the minimum number of coins needed to reach each amount
        int[][] dp = new int[amount + 1][coins.length + 1];

        // Fill the 2D array with the minimum number of coins needed to reach each amount
        for (int i = 0; i <= amount; i++) {
            for (int j = 0; j < coins.length; j++) {
                if (i >= coins[j]) {
