public int countRangeSum(int[] nums, int lower, int upper) {
    int[] sums = new int[nums.length + 1];
    for (int i = 0; i < nums.length; i++) {
        sums[i + 1] = sums[i] + nums[i];
    }

    // Merge sort to count the number of subarrays with sum in the range [lower, upper]
    int count = mergeSort(0, nums.length - 1);

    return count;
}

// Merge sort function to count the number of subarrays with sum in the range [lower, upper]
private int mergeSort(int start, int end) {
    if (start == end) {
        return 0;
    }
    int mid = start + (end - start) / 2;
    int count = mergeSort(start, mid) + mergeSort(mid + 1, end);

    int j = mid + 1, k = mid + 1;
    for (int i = start; i <= mid; i++) {
        while (j <= end && sums[j] - sums[i] < lower) j++;
        while (k <= end && sums[k] - sums[i] <= upper) k++;
        count += k - j;
    }

    // Sort the subarrays
    for (int i = start; i <= mid; i++) {
        int index = i - start;
        sums[index] = sums[start] + sums[index + 1] - sums[start + 1];
    }

    return count;
}
