import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[][] matrix = {{9, 9, 4}, {6, 6, 8}, {2, 1, 1}};
        System.out.println(longestIncreasingPath(matrix));
    }

    public static int longestIncreasingPath(int[][] matrix) {
        int m = matrix.length, n = matrix[0].length;
        int[][][] memo = new int[m][n][4];

        int ans = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                ans = Math.max(ans, dfs(matrix, memo, i, j));
            }
        }
        return ans;
    }

    public static int dfs(int[][] matrix, int[][][] memo, int i, int j) {
        if (memo[i][j][0] != 0 || memo[i][j][1] != 0 || memo[i][j][2] != 0 || memo[i][j][3] != 0) {
            return memo[i][j][0] + memo[i][j][1] + memo[i][j][2] + memo[i][j][3];
        }

        int maxLen = 0;
        for (int k = 0; k < 4; k++) {
            int ni = i + (k == 0 ? 0 : 1);
            int nj = j + (k == 1 ? 0 : 1);
            if (ni >= 0 && ni < m && nj >= 0 && nj < n && matrix[ni][nj] > matrix[i][j]) {
                maxLen = Math.max(maxLen, dfs(matrix, memo, ni, nj));
            }
        }

        memo[i][j][0] = maxLen;
        memo[i][j][1] = maxLen;
        memo[i][j][2] = maxLen;
        memo[i][j][3] = maxLen;
        return maxLen + 1;
    }
}
