def palindrome_pairs(words):
    result = []
    for i in range(len(words)):
        for j in range(i+1, len(words)):
            concat = words[i] + words[j]
            is_palindrome = True
            for left, right in zip(range(len(concat)), reversed(range(len(concat)))):
                if concat[left] != concat[right]:
                    is_palindrome = False
                    break
            if is_palindrome:
                result.append((i, j))
    return result

