    char_count = collections.Counter()
    left = 0
    maxLength = 0

    for right in range(len(s)):
        char_count[s[right]] += 1

        while len(char_count) > k:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                char_count.pop(s[left])
            left += 1

        maxLength = max(maxLength, right - left + 1)

    return maxLength
