void reverseString(std::vector<std::string>& s) {
    int left = 0, right = s.size() - 1;
    while (left < right) {
        std::string temp = s[left];
        s[left] = s[right];
        s[right] = temp;
        left++;
        right--;
    }
}

int main() {
    std::vector<std::string> s = {"h", "e", "l", "l", "o"};
    reverseString(s);
    for (const auto& word : s) {
        std::cout << word << " ";
    }
    std::cout << std::endl;
    return 0;
}
