string rearrangeString(string s, int k) {
    if (k == 0) return s;

    unordered_map<char, int> freq;
    for (char c : s) {
        freq[c]++;
    }

    priority_queue<pair<int, char>> max_heap;
    for (const auto& kv : freq) {
        max_heap.emplace(kv.second, kv.first);
    }

    string result;
