import heapq
from collections import defaultdict

def rearrange_string(s, k):
    if k == 0:
        return s

    freq = defaultdict(int)
    for c in s:
        freq[c] += 1

    max_heap = []
    for c, count in freq.items():
        heapq.heappush(max_heap, (-count, c))

    result = []
    while max_heap:
        for _ in range(k):
            count, c = heapq.heappop(max_heap)
            result.append(c)
            freq[c] -= 1
            if freq[c] > 0:
                heapq.heappush(max_heap, (-freq[c], c))
        if len(result) >= len(s):
            break

    if len(result) < len(s):
        result.extend(k - len(result), ' ')
    return ''.join(result)
