public class Solution {
    public boolean canMeasureWater(int jug1Capacity, int jug2Capacity, int targetCapacity) {
        // Check if the target capacity is greater than the sum of the two jugs' capacities
        if (targetCapacity > jug1Capacity + jug2Capacity) return false;

        // Check if either jug can hold the target capacity
        if (jug1Capacity == targetCapacity || jug2Capacity == targetCapacity 
            || jug1Capacity + jug2Capacity == targetCapacity) return true;

        // Calculate the greatest common divisor of the two jugs' capacities
        int gcd = gcd(jug1Capacity, jug2Capacity);

        // Check if the target capacity is divisible by the greatest common divisor
        return targetCapacity % gcd == 0;
    }

    // Function to calculate the greatest common divisor
    private int gcd(int a, int b) {
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
