int getMoneyAmount(int n) {
    int dp[n + 1][n + 1];
    for (int i = n - 1; i >= 1; i--) {
        for (int j = i + 1; j <= n; j++) {
            int min_cost = INT_MAX;
            for (int k = i; k < j; k++) {
                int cost = k + std::max(dp[i][k - 1], dp[k + 1][j]);
                min_cost = std::min(min_cost, cost);
            }
            dp[i][j] = min_cost;
        }
    }
    return dp[1][n];
}

int main() {
    int n = 10;
    std::cout << getMoneyAmount(n) << std::endl;
    return 0;
}
