    std::priority_queue<std::tuple<int, int, int>> min_heap;
    for (int i = 0; i < matrix.size(); i++) {
        min_heap.push({matrix[i][0], i, 0});
    }

    while (k > 1) {
        int row = std::get<1>(min_heap.top());
        int col = std::get<2>(min_heap.top());
        min_heap.pop();

        if (col + 1 < matrix[row].size()) {
            min_heap.push({matrix[row][col + 1], row, col + 1});
        }
        k--;
    }

    return std::get<0>(min_heap.top());
}

int main() {
    std::vector<std::vector<int>> matrix = {{1, 5, 9}, {10, 11, 13}, {12, 13, 15}};
    int k = 8;
    std::cout << kthSmallest(matrix, k) << std::endl;
    return 0;
}
