import java.util.*;

public class Solution {
    public String findLongestWord(String s, List<String> dictionary) {
        // Sort the dictionary in ascending order
        Collections.sort(dictionary);

        // Iterate through the sorted dictionary
        for (String word : dictionary) {
            // Check if the current word is a subsequence of the input string
            if (isSubsequence(s, word)) {
                // If the current word is longer than the longest found word, update the longest found word
                if (word.length() > longest.length()) {
                    longest = word;
                }
            }
        }
        return longest;
    }

    // Function to check if one string is a subsequence of another
    private boolean isSubsequence(String s, String word) {
        int i = 0, j = 0;
        while (i < s.length() && j < word.length()) {
            if (s.charAt(i) == word.charAt(j)) {
                j++;
            }
            i++;
        }
        return j == word.length();
    }
}
