import java.util.HashMap;
import java.util.List;

public class Solution {
    public List<String> findRestaurant(List<String> list1, List<String> list2) {
        // Create a map to store the index of each restaurant in list1
        HashMap<String, Integer> restaurantMap = new HashMap<>();
        for (int i = 0; i < list1.size(); i++) {
            restaurantMap.put(list1.get(i), i);
        }

        // Initialize the minimum sum and result list
        int minSum = Integer.MAX_VALUE;
        List<String> result = new ArrayList<>();

        // Iterate over list2 and find the restaurants that are in both lists
        for (String restaurant : list2) {
            // Check if the restaurant is in the map
            if (restaurantMap.containsKey(restaurant)) {
                // Calculate the total sum of the index and the map index
                int totalSum = restaurantMap.get(restaurant) + list2.indexOf(restaurant);
                // Update the minimum sum and result list if necessary
                if (totalSum < minSum) {
                    result.clear();
                    minSum = totalSum;
                    result.add(restaurant);
                } else if (totalSum == minSum) {
                    result.add(restaurant);
                }
            }
        }

        return result;
    }
}
