)

func kInversePairs(n int, k int) int {
	mod := big.NewInt(1000000007)
	dp := make([][]int, n+1)
	for i := 1; i <= n; i++ {
		dp[i] = make([]int, k+1)
		dp[i][0] = 1
		for j := 1; j <= k; j++ {
