```c++
#include <iostream>
#include <vector>
#include <string>

std::vector<int> exclusiveTime(int n, std::vector<std::string> logs) {
    std::vector<int> res(n, 0);
    std::vector<int> stack;
    int prev_time = 0;

    for (const auto& log : logs) {
        std::istringstream iss(log);
        std::string id, type, time;
        iss >> id >> type >> time;

        if (type == "start") {
            if (!stack.empty()) {
                res[stack.back()] += std::stoi(time) - prev_time;
            }
            stack.push_back(std::stoi(id));
            prev_time = std::stoi(time);
        } else {
            res[stack.back()] += std::stoi(time) - prev_time + 1;
            stack.pop_back();
            prev_time = std::stoi(time) + 1;
        }
    }

    return res;
}
