#include <iostream>
#include <vector>

// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

// Function to calculate the average of each level in a binary tree
std::vector<double> averageOfLevels(TreeNode* root) {
    std::vector<double> result;
    std::queue<TreeNode*> queue;
    queue.push(root);

    while (!queue.empty()) {
        int sum = 0;
        int count = 0;
        std::vector<TreeNode*> temp;
        while (!queue.empty()) {
            TreeNode* node = queue.front();
            queue.pop();
            sum += node->val;
            count++;
            if (node->left) temp.push_back(node->left);
            if (node->right) temp.push_back(node->right);
        }
        queue = temp;
        result.push_back((double)sum / count);
    }
    return result;
}

int main() {
    TreeNode* root = new TreeNode(3);
    root->left = new TreeNode(9);
    root->right = new TreeNode(20);
    root->right->left = new TreeNode(15);
    root->right->right = new TreeNode(7);

    std::vector<double> expectedOutput = {3.0, 14.5, 11.0};
    std::vector<double> actualOutput = averageOfLevels(root);

    for (int i = 0; i < actualOutput.size(); i++) {
        std::cout << actualOutput[i] << std::endl;
    }

    return 0;
}
