int shoppingOffers(const std::vector<int>& price, const std::vector<std::vector<int>>& special, const std::vector<int>& needs) {
    // Helper function to calculate the cost without applying any offers
    int no_offer = 0;
    for (int i = 0; i < needs.size(); ++i) {
        no_offer += needs[i] * price[i];
    }

    // Helper function to calculate the cost with applying an offer
    int with_offer = no_offer;
    for (const auto& offer : special) {
        int can_apply_offer = true;
        for (int i = 0; i < needs.size(); ++i) {
            if (offer[i] > 0) {
                needs[i] -= offer[i];
                if (needs[i] < 0) {
                    can_apply_offer = false;
                }
            }
        }
        if (can_apply_offer) {
            with_offer = std::min(with_offer, no_offer + offer.back());
        }
        for (int i = 0; i < needs.size(); ++i) {
            needs[i] += offer[i];
        }
    }

    return with_offer;
}
