import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int shoppingOffers(List<Integer> price, List<List<Integer>> special, List<Integer> needs) {
        // Helper function to calculate the cost without applying any offers
        int no_offer = 0;
        for (int i = 0; i < needs.size(); ++i) {
            no_offer += needs.get(i) * price.get(i);
        }

        // Helper function to calculate the cost with applying an offer
        int with_offer = no_offer;
        for (List<Integer> offer : special) {
            boolean can_apply_offer = true;
            for (int i = 0; i < needs.size(); ++i) {
                if (offer.get(i) > 0) {
                    needs.set(i, needs.get(i) - offer.get(i));
                    if (needs.get(i) < 0) {
                        can_apply_offer = false;
                    }
                }
            }
            if (can_apply_offer) {
                with_offer = Math.min(with_offer, no_offer + offer.get(special.size() - 1));
            }
            for (int i = 0; i < needs.size(); ++i) {
                needs.set(i, needs.get(i) + offer.get(i));
            }
        }

        return with_offer;
    }
}
