    def shoppingOffers(price: List[Int], special: List[List[Int]], needs: List[Int]): Int = {
        // Helper function to calculate the cost without applying any offers
        var no_offer = needs.foldLeft(0) { (acc, need) => acc + need * price(need) }

        // Helper function to calculate the cost with applying an offer
        var with_offer = no_offer
        for (offer <- special) {
            var can_apply_offer = true
            for (i <- needs.indices) {
                if (offer(i) > 0) {
                    needs(i) -= offer(i)
                    if (needs(i) < 0) {
                        can_apply_offer = false
                    }
                }
            }
            if (can_apply_offer) {
                with_offer = math.min(with_offer, no_offer + offer(special.length - 1))
            }
            for (i <- needs.indices) {
                needs(i) += offer(i)
            }
        }

        return with_offer
    }
}
