    needed = [0] * 20001
    for n in nums:
        freq[n] += 1
    for n in nums:
        if freq[n] == 0:
            continue
        if needed[n - 1] == 0:
            if freq[n + 1] > 0 and freq[n + 2] > 0:
                freq[n] -= 1
                freq[n + 1] -= 1
                freq[n + 2] -= 1
                needed[n + 2] += 1
            else:
                return False
        else:
            freq[n] -= 1
            needed[n - 1] -= 1
            needed[n] += 1
    return True
```



