#include <iostream>
#include <set>
#include <unordered_set>

class TreeNode {
public:
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
public:
    bool checkEqualTree(TreeNode* root) {
        std::unordered_set<int> seen;
        int total = sum(root, seen);
        if (total % 2 == 0) {
            seen.erase(total);
            return seen.find(total / 2) != seen.end();
        }
        return false;
    }

    int sum(TreeNode* node, std::unordered_set<int>& seen) {
        if (!node) return 0;
        int s = node->val + sum(node->left, seen) + sum(node->right, seen);
        seen.insert(s);
        return s;
    }
};
