    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(presses + 1, 0));
    dp[0][0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= presses; ++j) {
            dp[i][j] = dp[i][j - 1] * (i + 1) + (dp[i - 1][j - 1] if i > 0 else 0);
        }
    }

    return dp[n][presses];
}

