package main

import (
	"fmt"
	"sort"
)

func findNumberOfLIS(nums []int) int {
	n := len(nums)
	maxLength := 0
	ans := 0
	length := make([]int, n)
	count := make([]int, n)

	for i := 0; i < n; ++i {
		length[i] = count[i] = 1
		for j := 0; j < i; ++j {
			if nums[i] > nums[j] {
				if length[i] == length[j] + 1 {
					count[i] += count[j]
				} else if length[i] < length[j] + 1 {
					length[i] = length[j] + 1
					count[i] = count[j]
				}
			}
		}
		if maxLength == length[i] {
			ans += count[i]
		} else if maxLength < length[i] {
			maxLength = length[i]
			ans = count[i]
		}
	}

	return ans
}

func main() {
	nums := []int{1, 3, 5, 4, 7}
	fmt.Println(findNumberOfLIS(nums))
}
