import java.util.*;

public class Solution {
    public int numDistinctIslands(int[][] grid) {
        // Function to find all distinct islands in the grid
        Set<String> distinctIslands = new HashSet<>();

        // Iterate over each row and column of the grid
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == 1) {
                    // Initialize a new island
                    List<Point> island = new ArrayList<>();

                    // Perform a depth-first search to find all points in the island
                    dfs(r, c, island);

                    // Normalize the island by removing duplicates and sorting
                    island = normalize(island);

                    // Add the normalized island to the set of distinct islands
                    distinctIslands.add(islandToString(island));
                }
            }
        }

        // Return the number of distinct islands
        return distinctIslands.size();
    }

    // Function to perform a depth-first search to find all points in an island
    private void dfs(int r, int c, List<Point> island) {
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length || grid[r][c] == 0) {
            return;
        }

        island.add(new Point(r, c));
        grid[r][c] = 0;

        dfs(r + 1, c, island);
        dfs(r - 1, c, island);
        dfs(r, c + 1, island);
        dfs(r, c - 1, island);
    }

    // Function to normalize an island by removing duplicates and sorting
    private List<Point> normalize(List<Point> island) {
        Set<Point> uniquePoints = new HashSet<>();
        uniquePoints.addAll(island);
        List<Point> normalizedIsland = new ArrayList<>(uniquePoints);
        normalizedIsland.sort((p1, p2) -> {
            if (p1.x == p2.x) {
                return p1.y - p2.y;
            } else {
                return p1.x - p2.x;
            }
        });
        return normalizedIsland;
    }

    // Function to convert a list of points to a string
    private String islandToString(List<Point> island) {
        StringBuilder sb = new StringBuilder();
        for (Point point : island) {
            sb.append("(").append(point.x).append(", ").append(point.y).append(")");
        }
        return sb.toString();
    }

    // Inner class to represent a point in the grid
    private static class Point {
        int x;
        int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}
