std::vector<int> dailyTemperatures(const std::vector<int>& temperatures) {
    std::vector<int> result(temperatures.size(), 0);
    std::stack<int> stack;

    for (int i = 0; i < temperatures.size(); i++) {
        while (!stack.empty() && temperatures[i] > temperatures[stack.top()]) {
            int idx = stack.top();
            result[idx] = i - idx;
            stack.pop();
        }
        stack.push(i);
    }

    return result;
}
```



