int minCostClimbingStairs(std::vector<int> cost) {
    for (int i = 2; i < cost.size(); i++) {
        cost[i] += std::min(cost[i - 1], cost[i - 2]);
    }
    return std::min(cost.back(), cost.back() - 1);
}

