public class Solution {
    public boolean pyramidTransition(String bottom, String[] allowed) {
        // Create a mapping from the first two characters to the remaining characters
        Map<String, List<String>> mapping = new HashMap<>();
        for (String s : allowed) {
            String key = s.substring(0, 2);
            if (!mapping.containsKey(key)) {
                mapping.put(key, new ArrayList<>());
            }
            mapping.get(key).add(s.substring(2));
        }

        // Recursively check if the bottom string can be transformed into the top string
        return pyramidTransitionHelper(bottom, "", 0, mapping);
    }

    public boolean pyramidTransitionHelper(String bottom, String top, int idx, Map<String, List<String>> mapping) {
        if (bottom.length() == 1) {
            return true;
        }
        if (idx == bottom.length() - 1) {
            return pyramidTransitionHelper(top, "", 0, mapping);
        }
        String key = bottom.substring(idx, idx + 2);
        if (!mapping.containsKey(key)) {
            return false;
        }
        for (String c : mapping.get(key)) {
            if (pyramidTransitionHelper(bottom, top + c, idx + 1, mapping)) {
                return true;
            }
        }
        return false;
    }
}
