class Solution {
public:
    bool pyramidTransition(std::string bottom, std::vector<std::string> allowed) {
        // Create a mapping from the first two characters to the remaining characters
        std::map<std::string, std::vector<std::string>> mapping;
        for (const auto& s : allowed) {
            std::string key = s.substr(0, 2);
            if (mapping.find(key) == mapping.end()) {
                mapping[key] = {};
            }
            mapping[key].push_back(s.substr(2));
        }

        // Recursively check if the bottom string can be transformed into the top string
        return pyramidTransitionHelper(bottom, "", 0, mapping);
    }

    bool pyramidTransitionHelper(const std::string& bottom, std::string top, int idx, const std::map<std::string, std::vector<std::string>>& mapping) {
        if (bottom.length() == 1) {
            return true;
        }
        if (idx == bottom.length() - 1) {
            return pyramidTransitionHelper(top, "", 0, mapping);
        }
        std::string key = bottom.substr(idx, idx + 2);
        if (mapping.find(key) == mapping.end()) {
            return false;
