#include <iostream>
#include <vector>

int minSwapsCouples(std::vector<int>& row) {
    int n = row.size();
    std::vector<int> position(n);
    for (int i = 0; i < n; i++) {
        position[row[i]] = i;
    }

    int swaps = 0;
    for (int i = 0; i < n; i += 2) {
        int partner = row[i] + 1;
        if (row[i + 1] != partner) {
            int temp = row[i + 1];
            row[i + 1] = row[position[partner]];
            position[row[i + 1]] = position[partner];
            row[position[partner]] = temp;
            position[partner] = position[temp];
            swaps++;
        }
    }
    return swaps;
}

int main() {
    std::vector<int> row = {0, 2, 1, 3};
    std::cout << minSwapsCouples(row) << std::endl;
    return 0;
}
