        int n = row.length;
        int[] position = new int[n];
        for (int i = 0; i < n; i++) {
            position[row[i]] = i;
        }

        int swaps = 0;
        for (int i = 0; i < n; i += 2) {
            int partner = row[i] + 1;
            if (row[i + 1] != partner) {
                int temp = row[i + 1];
                row[i + 1] = row[position[partner]];
                position[row[i + 1]] = position[partner];
                row[position[partner]] = temp;
                position[partner] = position[temp];
                swaps++;
            }
        }
        return swaps;
    }

