int lenLongestFibSubseq(std::vector<int>& nums) {
    int n = nums.size();
    std::unordered_map<int, int> index;
    for (int i = 0; i < n; ++i)
        index[nums[i]] = i;

    std::unordered_map<int, int> longest;
    int ans = 0;

    for (int k = 0; k < n; ++k)
        for (int j = 0; j < k; ++j) {
            int i = index[nums[k] - nums[j]];
            if (i >= 0 && i < j) {
                longest[nums[k] * n + nums[j]] = longest[nums[j] * n + i] + 1;
                ans = std::max(ans, longest[nums[k] * n + nums[j]] + 1);
            }
        }

    return ans >= 3 ? ans : 0;
}

