#include <iostream>
#include <vector>
#include <algorithm>

int numDigitsLessThanN(std::vector<int>& digits, int n) {
    int ans = 0;
    int factor = 1;
    std::string n_str = std::to_string(n);
    for (int i = n_str.size() - 1; i >= 0; i--) {
        ans += std::lower_bound(digits.begin(), digits.end(), n_str[i]) - digits.begin() * factor;
        factor *= digits.size();
    }
    return ans;
}

int main() {
    std::vector<int> digits = {10, 5, 15, 3, 7, 18};
    int low = 7, high = 15;
    std::cout << numDigitsLessThanN(digits, low) << std::endl;
    std::cout << numDigitsLessThanN(digits, high) << std::endl;
    return 0;
}
