import java.util.*;
import java.lang.*;

public class Main {
    public static void main(String[] args) {
        List<Integer> digits = Arrays.asList(10, 5, 15, 3, 7, 18);
        int low = 7, high = 15;
        System.out.println(numDigitsLessThanN(digits, low));
        System.out.println(numDigitsLessThanN(digits, high));
    }

    public static int numDigitsLessThanN(List<Integer> digits, int n) {
        int ans = 0;
        int factor = 1;
        String n_str = String.valueOf(n);
        for (int i = n_str.length() - 1; i >= 0; i--) {
            ans += Collections.binarySearch(digits, n_str.charAt(i)) * factor;
            factor *= digits.size();
        }
        return ans;
    }
}
