        public int NumDigitsLessThanN(List<int> digits, int n) {
            int ans = 0;
            int factor = 1;
            string n_str = n.ToString();
            for (int i = n_str.Length - 1; i >= 0; i--) {
                ans += Array.BinarySearch(digits.ToArray(), n_str[i]) * factor;
                factor *= digits.Count;
            }
