import java.util.*;

public class Solution {
    public int numSquarefulPerms(int[] nums) {
        // Use a set to store unique elements and a counter to count occurrences
        Set<Integer> keySet = new HashSet<>();
        Map<Integer, Integer> counter = new HashMap<>();

        // Initialize the set and counter
        for (int num : nums) {
            keySet.add(num);
            counter.put(num, counter.getOrDefault(num, 0) + 1);
        }

        // Use a recursive function to count the number of permutations
        int result = dfs(0, keySet, counter);
        return result;
    }

    private int dfs(int idx, Set<Integer> keySet, Map<Integer, Integer> counter) {
        // Base case: if we have reached the end of the array
        if (idx == nums.length) {
            return 1;
        }

        // Initialize the count to 0
        int count = 0;

        // Iterate over the keys in the counter
        for (int key : counter.keySet()) {
            // Check if the key is in the set and if the key is squareful
            if (keySet.contains(key) && (idx == 0 || isSquareful(nums[idx - 1] + key))) {
                // Decrement the counter for the key
                counter.put(key, counter.get(key) - 1);
                // Place the key at the current index
                nums[idx] = key;
                // Recursively call the function to count the number of permutations
                count += dfs(idx + 1, keySet, counter);
                // Increment the counter for the key
                counter.put(key, counter.get(key) + 1);
            }
        }
        return count;
    }

    // Function to check if a number is squareful
    private boolean isSquareful(int num) {
        return (int) Math.sqrt(num) * (int) Math.sqrt(num) == num;
    }
}
