int maxTurbulenceSize(std::vector<std::vector<int>>& grid) {
    int n = grid.size();
    int result = 1;
    int i = 0;

    while (i < n - 1) {
        if (grid[i][0] == grid[i + 1][0]) {
            i += 1;
            continue;
