```go
package main

import (
	"container/heap"
	"fmt"
)

type priorityQueue struct {
	items []int
}

func (pq *priorityQueue) Len() int { return len(pq.items) }
func (pq *priorityQueue) Less(i, j int) bool {
	return pq.items[i] < pq.items[j]
}
func (pq *priorityQueue) Swap(i, j int) {
	pq.items[i], pq.items[j] = pq.items[j], pq.items[i]
}
func (pq *priorityQueue) Push(x interface{}) {
	pq.items = append(pq.items, x.(int))
}
func (pq *priorityQueue) Pop() interface{} {
	old := pq.items
	n := len(old)
	pq.items = old[:n-1]
	return pq.items[n-1]
}

func maxTurbulenceSize(arr []int) int {
	n := len(arr)
	pq := &priorityQueue{}
	heap.Init(pq)
	for i := 0; i < n; i++ {
		heap.Push(pq, arr[i])
	}
	result := 1
	for i := 0; i < n-1; i++ {
		if arr[i] == arr[i+1] {
			continue
		}
		if arr[i] > arr[i+1] {
			heap.Push(pq, arr[i+1])
		} else {
			heap.Push(pq, arr[i])
		}
		result = max(result, pq.Len())
	}
	return result
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func main() {
	arr := []int{0, 0, 0, 0, 1, 0, 1, 0, 0}
	fmt.Println(maxTurbulenceSize(arr))
}
