func maxTurbulenceSize(_ arr: [Int]) -> Int {
    let n = arr.count
    var result = 1
    var i = 0

    while i < n - 1 {
        if arr[i] == arr[i + 1] {
            i += 1
            continue
        }

        var j = i + 1
        while j < n - 1 && ((arr[j] > arr[j + 1]) !== (arr[j - 1] > arr[j])) {
            j += 1
        }

        result = max(result, j - i + 1)
        i = j
    }

    return result
