#include <iostream>
#include <vector>

int findKthPositive(std::vector<int>& nums, int k) {
    int left = 0, right = nums.size();
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] - mid - 1 < k) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left + k;
}

int main() {
    std::vector<int> nums = {4, 7, 9, 10};
    int k = 1;
    std::cout << findKthPositive(nums, k) << std::endl;
    return 0;
}
