import java.util.*;

public class Solution {
    public int largestValsFromLabels(int[] values, int[] labels, int numWanted, int useLimit) {
        // Create a list of tuples where each tuple contains a value and its corresponding label
        List<Tuple> items = new ArrayList<>();
        for (int i = 0; i < values.length; i++) {
            items.add(new Tuple(values[i], labels[i]));
        }

        // Sort the list of tuples by value in descending order
        items.sort((a, b) -> -a.value.compareTo(b.value));

        // Create a map to store the count of each label
        Map<Integer, Integer> labelCount = new HashMap<>();

        // Initialize the answer and the number of wanted labels
        int ans = 0;
        int numWantedLabels = numWanted;

        // Iterate over the sorted list of tuples
        for (Tuple item : items) {
            // If the label is not in the map or the count is less than the limit, add the value to the answer and increment the count
            if (!labelCount.containsKey(item.label)) {
                labelCount.put(item.label, 0);
            }
            if (labelCount.get(item.label) < useLimit) {
                ans += item.value;
                labelCount.put(item.label, labelCount.get(item.label) + 1);
                numWantedLabels--;
                if (numWantedLabels == 0) {
                    break;
                }
            }
        }

        return ans;
    }

    private static class Tuple {
        int value;
