    for (int i = 0; i < n; i++) {
        parents[i] = i;
    }

    std::sort(logs, logs + n, [](const int* log1, const int* log2) { return log1[0] < log2[0]; });

    int groupCount = n;
    for (int i = 0; i < n; i++) {
        int rootX = find(logs[i][1], parents);
        int rootY = find(logs[i][2], parents);
        if (rootX != rootY) {
            parents[rootX] = rootY;
            groupCount--;
        }
        if (groupCount == 1) {
            return logs[i][0];
        }
    }
    return -1;
}

int find(int x, int* parents) {
    return x == parents[x] ? x : (parents[x] = find(parents[x], parents));
}
