import java.util.*;
import java.util.stream.Collectors;

public class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int sum = Arrays.stream(nums).sum();
        if (sum % k != 0) return false;
        int target = sum / k;
        Arrays.sort(nums);
        return canPartitionKSubsetsHelper(nums, target, k, 0, new boolean[nums.length]);
    }

    private boolean canPartitionKSubsetsHelper(int[] nums, int target, int k, int start, boolean[] visited) {
        if (k == 1) return true;
        if (start >= nums.length) return false;
        for (int i = start; i < nums.length; i++) {
            if (!visited[i]) {
                visited[i] = true;
                if (nums[i] == target) return true;
                if (canPartitionKSubsetsHelper(nums, target, k - 1, i + 1, visited)) return true;
                visited[i] = false;
            }
        }
        return false;
    }
}
