import java.util.*;

public class Solution {
    public int minimumSemesters(int n, List<List<Integer>> relations) {
        // Create an adjacency list representation of the graph
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            graph.add(new ArrayList<>());
        }

        // Add edges to the graph
        for (List<Integer> relation : relations) {
            graph.get(relation.get(0)).add(relation.get(1));
        }

        // Initialize a queue to store the courses with 0 in-degree
        Queue<Integer> q = new LinkedList<>();
        for (int i = 1; i <= n; i++) {
            if (graph.get(i).size() == 0) {
                q.add(i);
            }
        }

        // Count the number of semesters
        int semesters = 0;
        while (!q.isEmpty()) {
            int size = q.size();
            semesters++;
            while (size-- > 0) {
                int course = q.poll();
                n--;

                // Remove the in-degree of the current course
                for (int next : graph.get(course)) {
                    graph.get(next).remove(course);
                    if (graph.get(next).size() == 0) {
                        q.add(next);
                    }
                }
            }
        }

        // Check if all courses have been processed
        return n == 0 ? semesters : -1;
    }
}
