    public int maxEqualRowsAfterFlips(String text) {
        Map<String, Integer> count = new HashMap<>();
        for (int i = 0; i < text.length(); i += 5) {
            String row = text.substring(i, i + 5);
            String flipped = row;
            for (char c : flipped.toCharArray()) {
                c = (char) (c - 'a');
            }
            count.put(row, count.getOrDefault(row, 0) + 1);
            count.put(flipped, count.getOrDefault(flipped, 0) + 1);
        }
        int maxCount = 0;
        for (Map.Entry<String, Integer> entry : count.entrySet()) {
            maxCount = Math.max(maxCount, entry.getValue());
        }
        return maxCount;
    }

    public static void main(String[] args) {
        String text = "ghiabcdefhelloadamhelloabcdefghi";
        System.out.println(new Solution().maxEqualRowsAfterFlips(text));
