namespace LeetCode {
    public class Solution {
        public int MaxEqualRowsAfterFlips(string text) {
            Dictionary<string, int> count = new Dictionary<string, int>();
            for (int i = 0; i < text.Length; i += 5) {
                string row = text.Substring(i, 5);
                string flipped = row;
                for (int j = 0; j < row.Length; j++) {
                    flipped[j] = (row[j] - 'a') + 'a';
                }
                count[row] = count.ContainsKey(row) ? count[row] + 1 : 1;
                count[flipped] = count.ContainsKey(flipped) ? count[flipped] + 1 : 1;
            }
            int maxCount = 0;
            foreach (KeyValuePair<string, int> pair in count) {
                maxCount = Math.Max(maxCount, pair.Value);
            }
            return maxCount;
        }
    }
}

public class Program {
    public static void Main() {
        string text = "ghiabcdefhelloadamhelloabcdefghi";
        Console.WriteLine(new LeetCode.Solution().MaxEqualRowsAfterFlips(text));
    }
