public class Solution {
    public String reverseParentheses(String s) {
        Stack<Integer> stack = new Stack<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                stack.push(i);
            } else if (c == ')') {
                int start = stack.pop();
                int end = i;
                // reversal of the substring
                s = s.substring(0, start) + s.substring(start + 1, end)[::-1] + s.substring(end + 1);
            }
        }
        return s;
    }
}
