#include <iostream>
#include <vector>
#include <algorithm>

int minHeightShelves(std::vector<std::vector<int>> books, int shelfWidth) {
    int n = books.size();
    int dp[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; ++i) {
        int width = 0, height = 0;
        int j = i;
        while (j >= 1) {
            width += books[j - 1][0];
            height = std::max(height, books[j - 1][1]);

            if (width <= shelfWidth) {
                dp[i] = std::min(dp[i], dp[j - 1] + height);
            }
            j--;
        }
    }

    return dp[n];
}

int main() {
    std::vector<std::vector<int>> books = {{100, 200}, {150, 250}, {100, 500}, {1000, 1000}};
    int shelfWidth = 1000;
    std::cout << minHeightShelves(books, shelfWidth) << std::endl;
    return 0;
}
