#include <iostream>
#include <cmath>

int nthUglyNumber(int n, int a, int b, int c) {
    int left = 1, right = 1000000000;
    int lcm_ab = a * b / __gcd(a, b);
    int lcm_ac = a * c / __gcd(a, c);
    int lcm_bc = b * c / __gcd(b, c);
    int lcm_abc = a * lcm_bc / __gcd(a, lcm_bc);

    while (left < right) {
        int mid = left + (right - left) / 2;
        int count = mid / a + mid / b + mid / c - mid / lcm_ab - mid / lcm_ac - mid / lcm_bc + mid / lcm_abc;
        if (count < n) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
}

int main() {
    std::cout << nthUglyNumber(3, 2, 3, 5) << std::endl;
    return 0;
}
