#include <vector>
#include <string>
#include <algorithm>
using namespace std;

class Solution {
public:
    string smallestStringWithSwaps(string s, vector<vector<int>>& pairs) {
        int n = s.size();
        vector<int> p(n, 0);
        for (int i = 0; i < n; ++i) {
            p[i] = i;
        }

        // find the parent for each index
        function<int(int)> find = [&](int x) {
            if (p[x] != x) {
                p[x] = find(p[x]);
            }
            return p[x];
        };

        // union-find and create the connected groups
        for (const auto& pair : pairs) {
            int root1 = find(pair[0]);
            int root2 = find(pair[1]);
            if (root1 != root2) {
                p[root2] = root1;
            }
        }

        vector<string> groups(n);
        for (int i = 0; i < n; ++i) {
            groups[find(i)].push_back(s[i]);
        }

        // Sort each group
        for (string& group : groups) {
            sort(group.begin(), group.end(), greater<char>());
        }

        // Build the result string
        string res;
        for (int i = 0; i < n; ++i) {
            char smallest_char = groups[find(i)].back(); 
            res += smallest_char;
            groups[find(i)].pop_back();
        }

        return res;
    }
};
