fn delNodes(root: Option<TreeNode>, to_delete: Vec<i32>) -> Vec<TreeNode> {
    let mut forest = Vec::new();
    let mut toDeleteSet = HashSet::new();
    for &val in &to_delete {
        toDeleteSet.insert(val);
    }
    helper(root, true, to_delete, &mut forest, &mut toDeleteSet);
    forest
