func longestWPI(_ hours: [Int]) -> Int {
    var score = 0
    var maxLength = 0
    var firstOccurrence = [Int: Int]()

    for i in 0..<hours.count {
        score += hours[i] > 8 ? 1 : -1
        if score > 0 {
            maxLength = i + 1
        } else {
            firstOccurrence[score, default: i] = i
            if let index = firstOccurrence.removeValue(forKey: score - 1) {
                maxLength = max(maxLength, i - index)
            }
        }
    }
    return maxLength
