import java.util.Arrays;

public class JobScheduling {
    public static void main(String[] args) {
        int[] startTime = {1, 2, 3, 3};
        int[] endTime = {3, 4, 5, 6};
        int[] profit = {50, 10, 40, 70};

        // Sort jobs by end time
        Arrays.sort(startTime, endTime, profit);

        // Initialize the dynamic programming table
        int[] dp = new int[startTime.length];
        dp[0] = profit[0];

        // Fill the dynamic programming table
        for (int i = 1; i < startTime.length; i++) {
            int L = latestNonConflict(i);
            dp[i] = Math.max(dp[i - 1], (L == -1) ? dp[i - 1] : dp[L] + profit[i]);
        }

        // Print the maximum profit
        System.out.println(dp[dp.length - 1]);
    }

    // Function to find the latest non-conflicting job
    private static int latestNonConflict(int index) {
        int startTimeToFind = endTime[index];
        int indexToFind = Arrays.binarySearch(endTime, startTimeToFind);
        if (indexToFind >= 0) {
            return indexToFind - 1;
        }
        return -1;
    }
}
