int stoneGameII(int n, int m) {
    std::vector<int> piles(n, 0);
    for (int i = n - 2; i >= 0; i--) {
        piles[i] += piles[i + 1];
    }

    // Use a cache to store the results of the recursive calls
    std::unordered_map<std::pair<int, int>, int> cache;
    int result = search(0, m, cache);
    return result;
