int search(int idx, int M, std::unordered_map<std::pair<int, int>, int>& cache) {
    if (idx + 2 * M >= n) {
        return piles[idx];
    }
    if (cache.find(std::make_pair(idx, M)) != cache.end()) {
        return cache[std::make_pair(idx, M)];
    }

    int max_value = 0;
    for (int x = 1; x <= 2 * M; x++) {
        max_value = std::max(max_value, piles[idx] - search(idx + x, max(M, x), cache));
    }
    cache[std::make_pair(idx, M)] = max_value;
    return max_value;
}
