int minOperations(std::vector<int>& arr1, std::vector<int>& arr2) {
    int n = arr1.size();
    std::vector<int> dp(n, std::numeric_limits<int>::max());
    for (int a : arr2) {
        std::vector<int> new_dp(n, std::numeric_limits<int>::max());
        int p = 0;
        for (int i = 0; i < n; ++i) {
            if (a < arr1[i]) {
                new_dp[i] = p;
