#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <unordered_map>

int MOD = 1000000007;

std::vector<std::vector<std::string>> board;

void solve() {
    int n = board.size();
    std::vector<std::vector<int>> dp(n, std::vector<int>(n, 0));
    std::vector<std::vector<int>> cnt(n, std::vector<int>(n, 0));

    board[0][0] = '0';
    board[n - 1][n - 1] = '0';
    cnt[n - 1][n - 1] = 1;

    for (int i = n - 1; i >= 0; i--) {
        for (int j = n - 1; j >= 0; j--) {
            if (board[i][j] != 'X') {
                std::vector<std::pair<int, int>> neighbors = {{i - 1, j}, {i, j - 1}, {i - 1, j - 1}};
                for (const auto& [x, y] : neighbors) {
                    if (x >= 0 && y >= 0) {
                        if (dp[i][j] < dp[x][y] + (board[i][j] - '0') + '0' * (board[x][y] - '0')) {
                            dp[i][j] = dp[x][y] + (board[i][j] - '0') + '0' * (board[x][y] - '0');
                            cnt[i][j] = cnt[x][y];
                        } else if (dp[i][j] == dp[x][y] + (board[i][j] - '0') + '0' * (board[x][y] - '0')) {
                            cnt[i][j] = (cnt[i][j] + cnt[x][y]) % MOD;
                        }
                    }
                }
            }
        }
    }

    std::cout << dp[0][0] << " " << cnt[0][0] << std::endl;
}

int main() {
    std::string input;
    std::getline(std::cin, input);
    std::vector<std::string> rows;
    while (input != "") {
        rows.push_back(input);
        std::getline(std::cin, input);
    }
    board = rows;

    solve();

    return 0;
}
