#include <vector>
#include <iostream>

std::vector<std::vector<int>> matrix_block_sum(const std::vector<std::vector<int>>& mat, int k) {
    int m = mat.size(), n = mat[0].size();
    std::vector<std::vector<int>> answer(m, std::vector<int>(n));

    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            for (int r = max(0, i - k); r < min(m, i + k + 1); ++r) {
                for (int c = max(0, j - k); c < min(n, j + k + 1); ++c) {
                    answer[i][j] += mat[r][c];
                }
            }
        }
    }

    return answer;
}

int main() {
    std::vector<std::vector<int>> mat = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
    int k = 1;
    std::vector<std::vector<int>> result = matrix_block_sum(mat, k);
    for (const auto& row : result) {
        for (const auto& num : row) {
            std::cout << num << " ";
        }
        std::cout << std::endl;
    }
    return 0;
}
