    for (int i = 0; i < n; i++) {
        counts[arr[i]]++;
    }

    std::set<int> uniqueCounts;
    for (auto& count : counts) {
        if (uniqueCounts.find(count.second) != uniqueCounts.end()) {
            return 0;
        }
        uniqueCounts.insert(count.second);
    }

    return 1;
}

