import java.util.concurrent.ConcurrentHashMap;

public class Solution {
    public int minJumps(int[] arr) {
        int n = arr.length;
        if (n <= 1) return 0;

        // Use a HashMap to store the indices of values
        Map<Integer, List<Integer>> valueIndices = new ConcurrentHashMap<>();
        for (int i = 0; i < n; ++i) {
            valueIndices.put(arr[i], new ArrayList<>());
            valueIndices.get(arr[i]).add(i);
        }

        // Use a queue to store the indices to be visited
        Queue<Integer> q = new LinkedList<>();
        boolean[] visited = new boolean[n];

        q.add(0);
        visited[0] = true;
        int steps = 0;

        while (!q.isEmpty()) {
            int size = q.size();

            for (int i = 0; i < size; ++i) {
