	"math"
)

func sumOfFourDivisors(nums []int) int {
	sum := 0
	for _, num := range nums {
		count := 0
		div_sum := 0
		for i := 1; i*i <= num; i++ {
			if num%i == 0 {
				count += (i*i == num) ? 1 : 2
				div_sum += i + (num/i)
				if count > 4 {
					break
				}
			}
		}
		if count == 4 {
			sum += div_sum
		}
	}
	return sum
}

