    public static String longest_diverse_string(int a, int b, int c) {
        String result = "";
        PriorityQueue<pair> pq = new PriorityQueue<>();
        pq.add(new pair(-a, 'a'));
        pq.add(new pair(-b, 'b'));
        pq.add(new pair(-c, 'c'));

        while (!pq.isEmpty()) {
            pair first = pq.peek();
            pq.poll();
            if (result.isEmpty() || result.charAt(result.length() - 1) != first.second) {
                result += first.second;
                first.first++;
                if (first.first < 0) {
                    pq.add(new pair(first.first, first.second));
                }
            } else if (!pq.isEmpty()) {
                pair second = pq.peek();
                pq.poll();
                result += second.second;
                second.first++;
                if (second.first < 0) {
                    pq.add(new pair(second.first, second.second));
                }
                if (first.first < 0) {
                    pq.add(new pair(first.first, first.second));
                }
            } else {
                break;
            }
        }
        return result;
    }

    private static class pair implements Comparable<pair> {
        int first;
        char second;

        public pair(int first, char second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public int compareTo(pair o) {
            return this.first - o.first;
        }
    }
