import java.util.Deque;
import java.util.LinkedList;

public class Solution {
    public String reformat(String s) {
        Deque<Character> letters = new LinkedList<>();
        Deque<Character> digits = new LinkedList<>();

        for (char c : s.toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                letters.add(c);
            } else {
                digits.add(c);
            }
        }

        if (Math.abs(letters.size() - digits.size()) > 1) {
            return "";
        }

        StringBuilder result = new StringBuilder();
        boolean useLetter = letters.size() > digits.size();

        while (!letters.isEmpty() || !digits.isEmpty()) {
            if (useLetter) {
                result.append(letters.poll());
            } else {
                result.append(digits.poll());
            }
            useLetter = !useLetter;
        }

        return result.toString();
    }
}
