fn is_possible_divide(nums: &Vec<i32>, k: i32) -> bool {
    let mut counts = std::collections::HashMap::new();
    for num in nums {
        counts.entry(*num).and_modify(|count| *count += 1).or_insert(1);
    }

    for i in 0..(k - 1) {
        for key in counts.keys() {
            let count = counts.get(key).unwrap();
            if *count > 0 {
                let target = *key + i + 1;
                if !counts.contains_key(&target) || counts.get(&target).unwrap_or(&0) < *count {
                    return false;
                }
                *counts.get_mut(&target).unwrap() -= *count;
            }
        }
    }
    true
}

