    minDeque = []
    left = 0
    right = 0
    longest = 0
    while right < len(nums):
        while maxDeque and nums[right] > maxDeque[-1]:
            maxDeque.pop()
        while minDeque and nums[right] < minDeque[-1]:
            minDeque.pop()

