// Function to remove leaf nodes from a binary tree
void removeLeafNodes(std::vector<int>& startTime, std::vector<int>& endTime, int queryTime) {
    // Base case: If the tree is empty, return
    if (startTime.empty() || endTime.empty()) {
        return;
    }

    // Remove leaf nodes
    for (int i = 0; i < startTime.size(); i++) {
        if (startTime[i] == queryTime && endTime[i] == queryTime) {
            startTime.erase(startTime.begin() + i);
            endTime.erase(endTime.begin() + i);
            i--;
        }
    }

    // Recursively remove leaf nodes from left and right subtrees
    removeLeafNodes(startTime, endTime, queryTime - 1);
    removeLeafNodes(startTime, endTime, queryTime + 1);
}

int main() {
    std::vector<int> startTime = {1, 2, 3};
    std::vector<int> endTime = {3, 2, 7};
    int queryTime = 4;

    removeLeafNodes(startTime, endTime, queryTime);

    // Print the updated startTime and endTime vectors
    for (int i = 0; i < startTime.size(); i++) {
        std::cout << startTime[i] << " ";
    }
    std::cout << std::endl;

    for (int i = 0; i < endTime.size(); i++) {
        std::cout << endTime[i] << " ";
    }
    std::cout << std::endl;

    return 0;
}
