import java.math.BigInteger;

public class Solution {
    public static void main(String[] args) {
        int[] balls = {1, 1};
        System.out.println(getProbability(balls));
    }

    private static BigInteger getProbability(int[] balls) {
        int sumBalls = Arrays.stream(balls).sum();
        BigInteger totalCombinations = BigInteger.ONE;
        for (int ball : balls) {
            totalCombinations = totalCombinations.multiply(BigInteger.valueOf(factorial(ball)));
        }

        int[] combinations = new int[balls.length];
        return dfs(balls, combinations, 0) / totalCombinations;
    }

    private static BigInteger dfs(int[] balls, int[] combinations, int currBall) {
        if (currBall == balls.length) {
            if (Arrays.equals(combinations, combinations[0])) {
                return BigInteger.valueOf(countCombinations(balls, combinations, currBall));
            } else {
                return BigInteger.ZERO;
            }
        }

        BigInteger result = BigInteger.ZERO;
        for (int i = 0; i <= balls[currBall]; i++) {
            combinations[currBall] = i;
            result = result.add(dfs(balls, combinations, currBall + 1));
        }
        return result;
    }

    private static int countCombinations(int[] balls, int[] combinations, int currBall) {
        int totalCombinations = 1;
        for (int i = 0; i < currBall; i++) {
            totalCombinations *= factorial(balls[i] + combinations[i]) / (factorial(balls[i]) * factorial(combinations[i]));
        }
        return totalCombinations;
    }
}
