std::vector<std::string> buildArray(std::vector<int>& target, int n) {
    std::vector<std::string> result;
    int current = 1;
    for (int num : target) {
        while (current < num) {
            result.push_back("Push");
            result.push_back("Pop");
            current += 1;
        }
        result.push_back("Push");
        current += 1;
    }
    return result;
}

