#include <iostream>
#include <vector>

int findLengthOfShortestSubarray(std::vector<int> arr) {
    int n = arr.size();
    int left = 0, right = n - 1;
    while (left < n - 1 && arr[left] <= arr[left + 1]) {
        left++;
    }
    if (left == n - 1) {
        return 0;
    }
    while (right > 0 && arr[right] >= arr[right - 1]) {
        right--;
    }
    int result = std::min(n - left - 1, right);
    int i = left, j = right;
    while (i <= left && j < n) {
        if (arr[i] <= arr[j]) {
            result = std::min(result, j - i - 1);
            i++;
        } else {
            j++;
        }
    }
    return result;
}

int main() {
    std::vector<int> arr = {1, 2, 3, 10, 4, 2, 3, 5};
    std::cout << findLengthOfShortestSubarray(arr) << std::endl;
    return 0;
}
