#include <iostream>
#include <vector>
#include <algorithm>

int maxProductPath(std::vector<std::vector<int>>& grid) {
    int m = grid.size(), n = grid[0].size(), mod = 1000000007;
    std::vector<std::vector<std::pair<int, int>>> dp(m, std::vector<std::pair<int, int>>(n, {0, 0}));
    dp[0][0] = {grid[0][0], grid[0][0]};
    for (int i = 1; i < m; ++i) {
        dp[i][0] = {grid[i][0] * dp[i - 1][0].first, grid[i][0] * dp[i - 1][0].first};
    }
    for (int j = 1; j < n; ++j) {
        dp[0][j] = {grid[0][j] * dp[0][j - 1].first, grid[0][j] * dp[0][j - 1].first};
    }
    for (int i = 1; i < m; ++i) {
        for (int j = 1; j < n; ++j) {
            if (grid[i][j] < 0) {
                dp[i][j] = std::min({grid[i][j] * dp[i - 1][j].first, grid[i][j] * dp[i][j - 1].first}, {dp[i - 1][j].second, dp[i][j - 1].second});
                dp[i][j] = std::max({grid[i][j] * dp[i - 1][j].second, grid[i][j] * dp[i][j - 1].second}, {dp[i - 1][j].first, dp[i][j - 1].first});
            } else {
                dp[i][j] = std::min({grid[i][j] * dp[i - 1][j].first, grid[i][j] * dp[i][j - 1].first}, {dp[i - 1][j].second, dp[i][j - 1].second});
                dp[i][j] = std::max({grid[i][j] * dp[i - 1][j].second, grid[i][j] * dp[i][j - 1].second}, {dp[i - 1][j].first, dp[i][j - 1].first});
            }
        }
    }
    return dp[m - 1][n - 1].first < 0 ? -1 : dp[m - 1][n - 1].first;
}

int main() {
    std::vector<std::vector<int>> grid = {{-1, -2, -3}, {-2, -3, -3}, {-3, -3, -2}};
    std::cout << maxProductPath(grid) << std::endl;
    return 0;
}
