int connectTwoGroups(const std::vector<std::vector<int>>& cost) {
    int size1 = cost.size();
    int size2 = cost[0].size();
    int min_cost[size2];

    for (int i = 0; i < size2; ++i) {
        min_cost[i] = cost[0][i];
    }

    for (int i = 1; i < size1; ++i) {
        for (int j = 0; j < size2; ++j) {
            min_cost[j] = std::min(min_cost[j], cost[i][j]);
        }
    }

    int total_cost = 0;
    for (int i = 0; i < size1; ++i) {
        total_cost += cost[i][0];
    }

    for (int j = 0; j < size2; ++j) {
        total_cost += min_cost[j];
    }

    return total_cost;
}

int main() {
    std::vector<std::vector<int>> cost = {{15, 96}, {36, 2}};
    std::cout << connectTwoGroups(cost) << std::endl;
    return 0;
}
