#include <vector>
#include <unordered_map>

bool canFormArray(std::vector<int>& arr, std::vector<std::vector<int>>& pieces) {
    std::unordered_map<int, std::vector<int>> map;
    for (const auto& piece : pieces) {
        map[piece[0]].push_back(piece[0]);
    }

    int i = 0;
    while (i < arr.size()) {
        if (arr[i] != map[arr[i]][0]) {
            return false;
        }
        for (int j = 0; j < map[arr[i]].size(); ++j) {
            if (arr[i] != map[arr[i]][j]) {
                return false;
            }
            i++;
        }
    }
    return true;
}
