#include <iostream>
#include <vector>
#include <algorithm>

int minCost(int n, std::vector<int> cuts) {
    cuts.insert(cuts.begin(), 0);
    cuts.push_back(n);
    std::sort(cuts.begin(), cuts.end());

    int size = cuts.size();
    std::vector<std::vector<int>> dp(size, std::vector<int>(size, 0));

    for (int len = 2; len < size; ++len) {
        for (int i = 0; i < size - len; ++i) {
            int j = i + len;
            dp[i][j] = std::numeric_limits<int>::max();
            for (int k = i + 1; k < j; ++k) {
                dp[i][j] = std::min(dp[i][j], dp[i][k] + dp[k][j] + cuts[j] - cuts[i]);
            }
        }
    }

    return dp[0][size - 1];
}

int main() {
    std::vector<int> list1 = {0, 1, 2, 3, 4, 5};
    int a = 3, b = 4;
    std::vector<int> list2 = {1000000, 1000001, 1000002};

    std::cout << minCost(list1.size(), list1) << std::endl;
    std::cout << minCost(a, b, list2) << std::endl;

    return 0;
}
