#include <vector>
#include <algorithm>

int minMoves(std::vector<int>& nums, int k) {
    int ones_pos = std::count(nums.begin(), nums.end(), 1);
    std::vector<int> to_move(ones_pos, 0);
    for (int i = 0; i < ones_pos; i++) {
        to_move[i] = nums[i * k] - nums[(i - k) * k];
    }
    int min_moves = to_move[k / 2];
    int move = min_moves;
    for (int i = 0; i < k / 2; i++) {
        move += to_move[i] - to_move[i + k / 2];
        min_moves = std::min(min_moves, move);
    }
    return min_moves;
}
