#include <iostream>
#include <unordered_map>

int check_ways(const std::vector<std::pair<int, int>>& pairs) {
    std::unordered_map<int, int> candidates;
    for (const auto& pair : pairs) {
        candidates[pair.first] += candidates[pair.first] + 1;
        candidates[pair.second] += candidates[pair.second] + 1;
    }

    int root_count = 0;
    for (const auto& count : candidates) {
        if (count.second == 1) {
            root_count++;
        }
    }
    return std::min(root_count, 2);
}

int main() {
    std::vector<std::pair<int, int>> pairs = {{1, 2}, {2, 3}};
    std::cout << check_ways(pairs) << std::endl;
    return 0;
}
