#include <vector>
#include <algorithm>

int minOperationsMaxProfit(std::vector<int>& customers, int boardingCost, int runningCost) {
    int rotations = 0, waiting = 0, onBoard = 0, profit = 0, maxProfit = 0, maxRotations = 0;
    while (customers.size() > 0 || waiting > 0) {
        if (customers.size() > 0) {
            waiting += customers[0];
            customers.erase(customers.begin());
        }
        onBoard = std::min(waiting, 4);
        waiting -= onBoard;
        profit += onBoard * boardingCost - runningCost;
        rotations++;

        if (profit > maxProfit) {
            maxProfit = profit;
            maxRotations = rotations;
        }
    }
    return maxRotations > 0 ? maxRotations : -1;
}
