std::vector<int> decode(const std::vector<int>& encoded) {
    int n = encoded.size() + 1;
    int total_xor = 0;

    for (int i = 1; i <= n; ++i) {
        total_xor ^= i;
    }

    int non_first_xor = 0;
    for (int i = 1; i < n - 1; i += 2) {
        non_first_xor ^= encoded[i];
    }

    std::vector<int> perm;
    perm.push_back(total_xor ^ non_first_xor);
    for (int i = 1; i < n; ++i) {
        perm.push_back(perm.back() ^ encoded[i - 1]);
    }

    return perm;
}

int main() {
    std::vector<int> encoded = {3, 1};
    std::vector<int> decoded = decode(encoded);
    for (int i : decoded) {
        std::cout << i << " ";
    }
    std::cout << std::endl;
    return 0;
}
