public int countHomogenous(String s) {
    int MOD = 1000000007;
    int count = 1, total = 0;
    for (int i = 1; i < s.length(); i++) {
        count = count + 1 if (s.charAt(i) == s.charAt(i - 1)) else 1;
        total = (total + count) % MOD;
    }
    return (total + count) % MOD;
}
