    for (int i = 0; i < points.length; i++) {
        if (x == points[i][0] || y == points[i][1]) {
            int distance = Math.abs(x - points[i][0]) + Math.abs(y - points[i][1]);
            if (distance < min_distance) {
                min_distance = distance;
                index = i;
            }
        }
    }
    return index;
}
