#include <iostream>
#include <set>
#include <algorithm>

int maximum_unique_subarray(int* nums, int n) {
    int max_sum = 0, current_sum = 0, left = 0;
    std::set<int> elements;

    for (int right = 0; right < n; right++) {
        while (nums[right] in elements) {
            elements.erase(nums[left]);
            current_sum -= nums[left];
            left++;
        }
        elements.insert(nums[right]);
        current_sum += nums[right];
        max_sum = std::max(max_sum, current_sum);
    }

    return max_sum;
}

int main() {
    int nums[] = {1, 2, 1, 1, 6, 4, 3, 5};
    int n = sizeof(nums) / sizeof(nums[0]);
    std::cout << maximum_unique_subarray(nums, n) << std::endl;
    return 0;
}
```
