        int[] dp = new int[nums.length];
        dp[0] = nums[0];
        dq.add(0);

        for (int i = 1; i < nums.length; ++i) {
            while (!dq.isEmpty() && dq.peek() < i - k) {
                dq.poll();
            }
            dp[i] = nums[i] + dp[dq.peek()];
            while (!dq.isEmpty() && dp[i] >= dp[dq.peekLast()]) {
                dq.pollLast();
            }
            dq.add(i);
        }

        return dp[nums.length - 1];
    }
