func maxResult(nums []int, k int) int {
	dp := make([]int, len(nums))
	dp[0] = nums[0]
	dq := []int{0}

	for i := 1; i < len(nums); i++ {
		for len(dq) > 0 && dq[0] < i-k {
			dq = dq[1:]
		}
		dp[i] = nums[i] + dp[dq[0]]
		for len(dq) > 0 && dp[i] >= dp[dq[len(dq)-1]] {
			dq = dq[:len(dq)-1]
		}
		dq = append(dq, i)
	}
	return dp[len(nums)-1]
}

