// Function to maximize XOR of two numbers
int maximizeXor(const std::vector<int>& nums, const std::vector<std::pair<int, int>>& queries) {
    std::vector<int> sorted_nums(nums.begin(), nums.end());
    std::sort(sorted_nums.begin(), sorted_nums.end());

    std::vector<std::pair<int, int>> sorted_queries(queries.begin(), queries.end());
    std::sort(sorted_queries.begin(), sorted_queries.end(), [](const auto& a, const auto& b) {
        return a.first < b.first;
    });

    std::unordered_map<int, int> trie;
    for (int num : sorted_nums) {
        trie[num] = num;
    }

    std::vector<int> ans(queries.size(), -1);
    int idx = 0;
    for (const auto& query : sorted_queries) {
        int x = query.first;
        int m = query.second;
        while (idx < sorted_nums.size() && sorted_nums[idx] <= m) {
            int t = sorted_nums[idx];
            idx++;
            int cur = trie[t];
            for (int j = 31; j >= 0; j--) {
                int bit = (t >> j) & 1;
                trie = cur[bit];
            }
            trie = cur;
        }
        trie = trie[x];
        int xor_value = 0;
        for (int j = 31; j >= 0; j--) {
            int bit = (x >> j) & 1;
            if (1 ^ bit in trie) {
                trie = trie[1 ^ bit];
                xor_value |= 1 << j;
            } else {
                trie = trie[bit];
            }
        }
        ans[query.second] = xor_value;
    }
    return ans;
}

