#include <iostream>
#include <vector>

bool canBeIncreasing(std::vector<int>& nums) {
    int count = 0;
    for (int i = 1; i < nums.size(); ++i) {
        if (nums[i - 1] >= nums[i]) {
            count++;
            if (count > 1) return false;
            if (i > 1 && nums[i - 2] >= nums[i] && i < nums.size() - 1 && nums[i - 1] >= nums[i + 1]) return false;
        }
    }
    return true;
}

int main() {
    std::vector<int> nums = {1, 2, 10, 5, 7};
    std::cout << canBeIncreasing(nums) << std::endl;
    return 0;
}
