#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> obstacles = {1, 2, 3, 2};
    std::vector<int> ans(obstacles.size(), 0);

    std::vector<int> dp;
    for (int obstacle : obstacles) {
        int index = std::lower_bound(dp.begin(), dp.end(), obstacle) - dp.begin();
        ans[index] = index + 1;
        if (index == dp.size()) {
            dp.push_back(obstacle);
        } else {
            dp[index] = obstacle;
        }
    }

    for (int i : ans) {
        std::cout << i << " ";
    }
    std::cout << std::endl;

    return 0;
}
